-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Vector3 = CS.UnityEngine.Vector3
local CanvasGroup = CS.UnityEngine.CanvasGroup
local Time = CS.UnityEngine.Time
local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils

local IdolLive3D_Utils = import('Game.IdolLive3D.IdolLive3D_Utils')

---@type Queue
local Queue = import("Game.DreamSpace.Tools.Queue")


-- ========================================================


-- 解锁判断条件:
local tapNum = 10           -- 玩家需要至少点击 10次
local targetDuration = 3.5  -- 若玩家在上一波 10 次点击的耗时不超过 targetDuration 秒, 即解锁成功


-- ========================================================



function IdolLive3D_SecretBtn:__init(  )
end


function IdolLive3D_SecretBtn:__delete()
end



function IdolLive3D_SecretBtn:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    -- local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    -- if behaviourAction then
    --     behaviourAction.UpdateAction = function(behaviourAction)
    --         self:Update()
    --     end
    -- end
    -- ================== self ================:

    self.queue = Queue.New(tapNum)
end



-- function IdolLive3D_SecretBtn:Update()
-- end



function IdolLive3D_SecretBtn:OnDestroy()
    self.queue:Clear()
    self.queue = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


----------------------------------------------------------


function IdolLive3D_SecretBtn:OnClickBtn()
    --printError("按下 count = " .. tostring(self.count))
    while self.queue:Count() >= tapNum do 
        self.queue:RemoveFirst()
    end 
    self.queue:AddLast( Time.time )
    ---
    local duration = self.queue:PeekLast() - self.queue:PeekFirst()
    --print("last: " .. tostring(self.queue:PeekLast()) .. ", fst = " .. tostring(self.queue:PeekFirst()) .. ", num = " .. tostring(self.queue:Count()) .. "; 间隔: " .. tostring(duration)  )
    if self.queue:Count() == tapNum and duration < targetDuration then 
        print("达成 深度互动 和谐 破解条件 !!!!!!! ")
        ---
        local isDeleteFile = IdolLive3D_Utils.TryReMoveHeXieFile()  
        if isDeleteFile then 
            print("成功删除 和谐文件")
        else 
            print("未找到 和谐文件 或其目录, 啥也没干")
        end 
    end 
end 



return IdolLive3D_SecretBtn
